package com.amit.headroom;
import android.app.PendingIntent;import android.appwidget.AppWidgetManager;import android.appwidget.AppWidgetProvider;import android.content.*;import android.net.Uri;import android.widget.RemoteViews;
public class HeadRoomWidget extends AppWidgetProvider{public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}static void update(Context c,AppWidgetManager m,int id){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.headroom_widget);Intent service=new Intent(c,HeadRoomWidgetService.class);service.putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);service.setData(Uri.parse(service.toUri(Intent.URI_INTENT_SCHEME)));v.setRemoteAdapter(R.id.widgetList,service);v.setEmptyView(R.id.widgetList,R.id.widgetEmpty);Intent open=new Intent(c,MainActivity.class);v.setOnClickPendingIntent(R.id.widgetTitle,PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE));m.updateAppWidget(id,v);}}